/**
 * Notifications screen.
 *
 * Lists budget alerts and reminders generated by the backend. Users can mark a
 * single notification as read (tap), mark all read, or delete one. Unread items
 * are visually highlighted. Pull-to-refresh re-fetches the list.
 */
import React, { useCallback, useState } from 'react';
import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import { NotificationApi } from '../../api/services';
import { EmptyState, ErrorBanner, Loading } from '../../components/UI';
import { colors, spacing, font, radius } from '../../theme';

// Map a notification type to an accent color and glyph.
const TYPE_META = {
  info: { color: colors.primary, icon: 'ℹ️' },
  warning: { color: colors.warning, icon: '⚠️' },
  danger: { color: colors.danger, icon: '🚨' },
};

export default function NotificationsScreen() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setError('');
    try {
      const data = await NotificationApi.list();
      setItems(data.notifications);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const markRead = async (id) => {
    try {
      await NotificationApi.markRead(id);
      setItems((prev) => prev.map((n) => (n.id === id ? { ...n, isRead: 1 } : n)));
    } catch (err) {
      setError(err.message);
    }
  };

  const markAll = async () => {
    try {
      await NotificationApi.markAllRead();
      setItems((prev) => prev.map((n) => ({ ...n, isRead: 1 })));
    } catch (err) {
      setError(err.message);
    }
  };

  const remove = async (id) => {
    try {
      await NotificationApi.remove(id);
      setItems((prev) => prev.filter((n) => n.id !== id));
    } catch (err) {
      setError(err.message);
    }
  };

  const renderItem = ({ item }) => {
    const meta = TYPE_META[item.type] || TYPE_META.info;
    return (
      <Pressable
        style={[styles.row, item.isRead === 0 && styles.unread]}
        onPress={() => item.isRead === 0 && markRead(item.id)}
      >
        <Text style={styles.icon}>{meta.icon}</Text>
        <View style={styles.body}>
          <Text style={[styles.title, { color: meta.color }]}>{item.title}</Text>
          <Text style={styles.message}>{item.body}</Text>
          <Text style={styles.time}>{item.createdAt}</Text>
        </View>
        <Pressable onPress={() => remove(item.id)} accessibilityLabel="Delete notification">
          <Text style={styles.delete}>✕</Text>
        </Pressable>
      </Pressable>
    );
  };

  if (loading) return <Loading />;

  return (
    <View style={styles.flex}>
      <ErrorBanner message={error} onRetry={load} />
      {items.length > 0 ? (
        <Pressable style={styles.markAll} onPress={markAll}>
          <Text style={styles.markAllText}>Mark all as read</Text>
        </Pressable>
      ) : null}
      <FlatList
        data={items}
        keyExtractor={(n) => String(n.id)}
        renderItem={renderItem}
        contentContainerStyle={items.length === 0 ? styles.emptyWrap : styles.listContent}
        refreshing={refreshing}
        onRefresh={() => {
          setRefreshing(true);
          load();
        }}
        ListEmptyComponent={
          <EmptyState title="No notifications" message="Budget alerts and reminders will show up here." emoji="🔔" />
        }
      />
    </View>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: colors.background },
  markAll: { padding: spacing.md, alignItems: 'flex-end' },
  markAllText: { color: colors.primary, fontWeight: '700', fontSize: font.small },
  listContent: { padding: spacing.md, paddingTop: 0 },
  emptyWrap: { flexGrow: 1 },
  row: {
    flexDirection: 'row', backgroundColor: colors.surface, borderRadius: radius.md,
    padding: spacing.md, marginBottom: spacing.sm, alignItems: 'flex-start',
  },
  unread: { borderLeftWidth: 4, borderLeftColor: colors.primary },
  icon: { fontSize: 20, marginRight: spacing.md },
  body: { flex: 1 },
  title: { fontSize: font.body, fontWeight: '700' },
  message: { fontSize: font.small, color: colors.text, marginTop: 2 },
  time: { fontSize: font.tiny, color: colors.textMuted, marginTop: spacing.xs },
  delete: { color: colors.textMuted, fontSize: font.body, paddingHorizontal: spacing.sm },
});
